"""Synthetic picture fixtures for the Photos to PDF tests (Tool Pack 31).

    python tests/fixtures/photos-to-pdf-fixtures.py

writes tests/fixtures/photos-to-pdf-fixtures.json: small pictures made with Pillow (an
implementation independent of the tool), each with the values the tests must find in them.
Every picture is synthetic: a gradient with a few blocks, no real photograph.
Widths are all different so the order of pages in a PDF can be proved from the file alone.
"""
import base64, hashlib, io, json, os
from PIL import Image, ImageDraw

HERE = os.path.dirname(os.path.abspath(__file__))


def art(w, h, mode="RGB", hue=0):
    im = Image.new("RGB", (w, h))
    px = im.load()
    for y in range(h):
        for x in range(w):
            px[x, y] = ((x * 255 // max(1, w - 1) + hue) % 256, (y * 255 // max(1, h - 1)) % 256, (x + y + hue * 3) % 256)
    d = ImageDraw.Draw(im)
    d.rectangle([2, 2, w // 3, h // 3], fill=(200, 30, 30))
    return im.convert(mode) if mode != "RGB" else im


def save(im, fmt, **kw):
    buf = io.BytesIO()
    im.save(buf, fmt, **kw)
    return buf.getvalue()


def exif_orientation(value):
    # a minimal big-endian TIFF with one Orientation tag, wrapped as an APP1 segment
    tiff = bytes([0x4D, 0x4D, 0, 0x2A, 0, 0, 0, 8, 0, 1, 0x01, 0x12, 0, 3, 0, 0, 0, 1, 0, value, 0, 0, 0, 0, 0, 0])
    body = b"Exif\x00\x00" + tiff
    return b"\xff\xe1" + (len(body) + 2).to_bytes(2, "big") + body


def with_exif(jpeg, value):
    return jpeg[:2] + exif_orientation(value) + jpeg[2:]


def entry(name, data, **expect):
    return {"name": name, "base64": base64.b64encode(data).decode(), "sha256": hashlib.sha256(data).hexdigest(), "bytes": len(data), **expect}


items = []
items.append(entry("rgb-baseline", save(art(64, 40), "JPEG", quality=90), format="jpeg", width=64, height=40, components=3, orientation=1, strategy="keep"))
items.append(entry("rgb-progressive", save(art(48, 72, hue=40), "JPEG", quality=85, progressive=True), format="jpeg", width=48, height=72, components=3, orientation=1, strategy="keep"))
items.append(entry("gray-baseline", save(art(56, 56, "L"), "JPEG", quality=90), format="jpeg", width=56, height=56, components=1, orientation=1, strategy="keep"))
items.append(entry("cmyk", save(art(40, 40, "CMYK"), "JPEG", quality=90), format="jpeg", width=40, height=40, components=4, orientation=1, strategy="redraw"))
base = save(art(80, 50, hue=90), "JPEG", quality=90)
items.append(entry("exif-turn-6", with_exif(base, 6), format="jpeg", width=80, height=50, components=3, orientation=6, strategy="redraw"))
items.append(entry("exif-turn-1", with_exif(base, 1), format="jpeg", width=80, height=50, components=3, orientation=1, strategy="keep"))
items.append(entry("png-rgba", save(art(52, 30).convert("RGBA"), "PNG"), format="png", width=52, height=30))
items.append(entry("webp", save(art(44, 44, hue=10), "WEBP", quality=80), format="webp", width=44, height=44))
items.append(entry("gif", save(art(20, 20).convert("P"), "GIF"), format="gif", width=20, height=20))
items.append(entry("truncated-jpeg", save(art(60, 60), "JPEG")[:40], format="jpeg", width=None, height=None))
items.append(entry("not-an-image", b"This is plain text, not a picture.", format="unknown"))

with open(os.path.join(HERE, "photos-to-pdf-fixtures.json"), "w") as f:
    json.dump({"$comment": "Generated by photos-to-pdf-fixtures.py (Pillow). Synthetic pictures only.", "items": items}, f, indent=1)
print("wrote", len(items), "fixtures")
